/* Panels: the doors to packs that are not out yet. The chair and the backpack (Focus), the photo frame
   (Orbit), the arrows to the kitchen and the garden (Living) and the lighthouse figurine (Lighthouse).
   Each opens a small "coming soon" card with a preview of the pack and a waitlist link (opened in the
   browser through /api/link, only when clicked). The previews are the pack pictures from
   casa.adrianofontanari.com, drawn for Casa. */
(function () {
  'use strict';
  const P = window.CasaPanels;
  if (!P) return;
  const { el } = P;
  const WAITLIST = 'https://casa.adrianofontanari.com/#notify';
  const IMG = {"chair": "data:image/webp;base64,", "backpack": "data:image/webp;base64,", "orbit": "data:image/webp;base64,", "kitchen": "data:image/webp;base64,", "garden": "data:image/webp;base64,", "lighthouse": "data:image/webp;base64,"};

  P.css(`
.sn-shot{display:block;width:100%;height:auto;aspect-ratio:16/10;object-fit:cover;margin:0 0 14px;border:3px solid var(--cp-navy);
  image-rendering:pixelated;background:#1b2033}
.sn-badge{display:inline-block;margin:0 0 12px;padding:3px 8px;background:var(--cp-yellow);color:var(--cp-navy);
  font:700 11px/1.2 var(--cp-sans);letter-spacing:.08em;text-transform:uppercase;box-shadow:2px 2px 0 var(--cp-navy)}
.sn-text{margin:0 0 6px;font:16px/1.45 var(--cp-sans);color:var(--cp-ink)}
.sn-pack{margin:0 0 18px;font-size:13px;color:var(--cp-muted)}
.sn-status{margin:12px 0 0;font-size:13px;color:var(--cp-muted)}
`);

  function soon(id, title, text, pack, alt) {
    P.register(id, {
      title,
      size: 's',
      render(ctx) {
        const status = el('p', { class: 'sn-status', role: 'status', 'aria-live': 'polite' });
        const join = el('button', { class: 'cp-btn cp-primary', type: 'button', dataset: { autofocus: '' } }, 'Join the waitlist');
        join.addEventListener('click', async () => {
          join.disabled = true;
          const r = await ctx.api('link', { method: 'POST', body: { url: WAITLIST } });
          join.disabled = false;
          if (!ctx.alive()) return;
          status.textContent = r.ok ? 'Opened in your browser.' : P.errorLine(r, 'Could not open the browser') + ' The address is ' + new URL(WAITLIST).host + '.';
        });
        ctx.clear(ctx.body);
        if (IMG[id]) ctx.body.append(el('img', { class: 'sn-shot', src: IMG[id], alt: alt || '' }));
        ctx.body.append(el('span', { class: 'sn-badge', text: 'Coming soon' }), el('p', { class: 'sn-text', text }),
          el('p', { class: 'sn-pack', text: pack }), join, status);
      },
    });
  }

  soon('chair', 'The chair', 'Sit for 30 minutes and the chair catches fire: time to stand up and stretch. Stand up and it goes out.', 'Part of the Focus pack.',
    'A desk chair with small flames along its seat.');
  soon('backpack', 'The backpack', 'Every file in your vault by type, to search and open. Drop a file on it and Casa files it in your vault.', 'Part of the Focus pack: your day hour by hour, the chair and the backpack.',
    'The desk wall in the afternoon, from the Focus pack.');
  soon('orbit', 'Orbit', 'Everyone you know, on one map: one note per person, linked from your meetings and daily notes. Before you meet someone, Orbit hands you the card.', 'The Orbit pack: a personal and professional CRM.',
    'Orbit: the people from your notes in orbit around your home, with a desk and a telescope.');
  soon('kitchen', 'The kitchen', 'The shopping list on the fridge, your next trip by the door, and a recipe book with every recipe you own.', 'Part of the Living pack: the kitchen and the garden.',
    'The kitchen: a list on the fridge, a recipe book on the counter, the buddy cooking and the dog waiting.');
  soon('garden', 'The garden', 'Photos from your favourite places hang on the line, and every tag you pick gets a crate to browse.', 'Part of the Living pack: the kitchen and the garden.',
    'Casa Garden: maples and a greenhouse, photos on a line, crates labelled Ideas, Books and Trips.');
  soon('lighthouse', 'Lighthouse', 'For stressful days: say what is going on and it shows only what helps now. Self-help exercises based on CBT and ACT, a daily journal, a breathing light. Not therapy.', 'The Lighthouse pack.',
    'The lighthouse at dusk: its beam sweeps over a calm sea while the buddy sits on the jetty.');
})();
